        groundWireService.borrow(id, new BorrowRequest("bw-race", "INT-1101",
                List.of(item(W1, 1)), T0));
        openBreaker(id, "race-1");

        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch ready = new CountDownLatch(2);
