    // 此后原失败参数再用同键即异参 409
    mockMvc.perform(post("/api/tickets/" + id + "/ground-wires/borrow")
                    .contentType(MediaType.APPLICATION_JSON).content(badBody))
            .andExpect(status().isConflict());
}

